    withCamera,
    withMicrophone,
    reason: "accept_call",
    allowCameraFailure: withCamera,
    noticeOnCameraFailure: "\u672A\u83B7\u5F97\u6444\u50CF\u5934\u6743\u9650\uFF0C\u5DF2\u5207\u6362\u4E3A\u8BED\u97F3\u63A5\u542C"
